import React, { useState } from 'react'; // Import useState
import { Link } from 'react-router-dom';

function Navbar({ darkMode, toggleDarkMode }) {
  // State to manage the visibility of the mobile menu
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Function to toggle the mobile menu state
  const toggleMobileMenu = () => {
    setIsMobileMenuOpen(!isMobileMenuOpen);
  };

  return (
    <nav className="w-full bg-white dark:bg-zinc-900 shadow-md dark:shadow-lg p-4 flex flex-wrap justify-between items-center sticky top-0 z-10">

      {/* Site Title Link */}
      <Link to="/" className="text-xl font-bold text-blue-600 dark:text-blue-400 hover:text-blue-800 dark:hover:text-blue-300 transition-colors duration-200">
        FB Downloader
      </Link>

      {/* Mobile Menu Toggle Button (Hamburger Icon) */}
      {/* Appears only on medium screens and below (md:hidden) */}
      <button
        onClick={toggleMobileMenu}
        className="md:hidden p-2 rounded-md text-zinc-700 dark:text-zinc-200 hover:bg-zinc-200 dark:hover:bg-zinc-700 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400"
        aria-label="Toggle navigation menu"
      >
        {/* Hamburger Icon (or Close Icon when menu is open) */}
        {isMobileMenuOpen ? (
          // Close Icon (X)
          <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          // Hamburger Icon
          <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        )}
      </button>

      {/* Navigation Links and Dark Mode Toggle Container */}
      {/* Hidden on small screens by default (hidden) */}
      {/* Flex layout on medium screens and up (md:flex) */}
      {/* When mobile menu is open (isMobileMenuOpen), it becomes flex */}
      {/* Uses flex-col for vertical stacking on all screen sizes when visible */}
      {/* Adds vertical space between items (space-y-2) */}
      {/* Full width on small screens when open (w-full) */}
      <div className={`${isMobileMenuOpen ? 'flex' : 'hidden'} md:flex flex-col md:flex-row items-center space-y-2 md:space-y-0 md:space-x-4 w-full md:w-auto mt-2 md:mt-0`}>

         {/* How to Use Link */}
         <Link
           to="/how-to-use"
           className="text-zinc-700 dark:text-zinc-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200"
           onClick={() => setIsMobileMenuOpen(false)} // Close menu on link click
         >
           How to Use
         </Link>

         {/* About Us Link */}
         <Link
           to="/about-us"
           className="text-zinc-700 dark:text-zinc-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200"
           onClick={() => setIsMobileMenuOpen(false)} // Close menu on link click
         >
           About Us
         </Link>

         {/* Contact Us Link */}
         <Link
           to="/contact-us"
           className="text-zinc-700 dark:text-zinc-300 hover:text-blue-600 dark:hover:text-blue-400 transition-colors duration-200"
           onClick={() => setIsMobileMenuOpen(false)} // Close menu on link click
         >
           Contact Us
         </Link>

        {/* Dark Mode Toggle Button */}
        <button
          onClick={toggleDarkMode}
          className="p-2 rounded-full bg-zinc-200 dark:bg-zinc-700 text-zinc-700 dark:text-zinc-200 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 transition-colors duration-300"
          aria-label="Toggle Dark Mode"
        >
          {darkMode ? (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
            </svg>
          ) : (
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
            </svg>
          )}
        </button>

      </div>
    </nav>
  );
}

export default Navbar;
